const DAY_MS = 86_400_000;

/** `#review?q=x&sort=-age` → the tab and its params. */
function parseHash(hash        ) {
  const [tab = "", query = ""] = hash.replace(/^#/, "").split("?");
  return { tab, params: new URLSearchParams(query) };
}

const filterKeys =    (filters             ) =>
  filters.flatMap((f) => (f.kind === "range" ? [`${f.key}_min`, `${f.key}_max`] : [f.key]));

function stateFrom   (params                 , filters             )             {
  const f                         = {};
  for (const key of filterKeys(filters)) {
    const v = params.get(key);
    if (v) f[key] = v;
  }
  return { q: params.get("q") ?? "", sort: params.get("sort") ?? "", f };
}

function hashFor(tab        , state            ) {
  const p = new URLSearchParams();
  if (state.q.trim()) p.set("q", state.q.trim());
  if (state.sort) p.set("sort", state.sort);
  for (const [k, v] of Object.entries(state.f)) if (v) p.set(k, v);
  const query = String(p);
  return `#${tab}${query ? `?${query}` : ""}`;
}

// A date filter is a whole local day: from its start to the end of the `max` day.
function bound(unit                , text        , end         ) {
  if (unit === "usd") return Number.isFinite(Number(text)) ? Math.round(Number(text) * 100) : null;
  const [y, m, d] = text.split("-").map(Number);
  if (!y || !m || !d) return null;
  return new Date(y, m - 1, d).getTime() + (end ? DAY_MS - 1 : 0);
}

function applyTable   (rows     , columns             , filters             , state            ) {
  const words = state.q.toLowerCase().split(/\s+/).filter(Boolean);
  const kept = rows.filter((row) => {
    if (words.length) {
      const hay = columns
        .map((c) => c.text(row))
        .join(" ")
        .toLowerCase();
      if (!words.every((w) => hay.includes(w))) return false;
    }
    return filters.every((f) => {
      // A server-paged table has no `value`: the server filtered already.
      if (f.kind === "select") return !state.f[f.key] || !f.value || f.value(row) === state.f[f.key];
      if (f.kind === "check") return true;
      if (f.kind === "text")
        return !state.f[f.key] || !f.value || f.value(row).includes(state.f[f.key]          );
      const min = state.f[`${f.key}_min`];
      const max = state.f[`${f.key}_max`];
      if (!min && !max) return true;
      const v = f.value(row);
      if (v == null) return false;
      const lo = min ? bound(f.unit, min, false) : null;
      const hi = max ? bound(f.unit, max, true) : null;
      return (lo == null || v >= lo) && (hi == null || v <= hi);
    });
  });
  const desc = state.sort.startsWith("-");
  const column = columns.find((c) => c.key === state.sort.replace(/^-/, ""));
  if (!column) return kept;
  const key = column.sort ?? column.text;
  return kept
    .map((row) => ({ row, k: key(row) }))
    .sort((a, b) => {
      const order =
        typeof a.k === "number" && typeof b.k === "number"
          ? a.k - b.k
          : String(a.k).localeCompare(String(b.k));
      return desc ? -order : order;
    })
    .map(({ row }) => row);
}

/** Next sort after clicking a header: the same column flips, another starts at its natural direction. */
function nextSort   (current        , column           ) {
  if (current === column.key) return `-${column.key}`;
  if (current === `-${column.key}`) return column.key;
  return column.desc ? `-${column.key}` : column.key;
}

                               
               
                       
                       
                
                                                                        
                             
                          
                                        
                                                    
     
                                                                                                   
                                                                                                
     
                                                                           
                                                                                                          
                            
                           
  

function createTable   (doc          , opts                 ) {
  const { columns, filters } = opts;
  let state             = { q: "", sort: "", f: {} };
  let rows      = [];
  const el =                                        (tag   , cls         , text         ) => {
    const node = doc.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  };

  const root = el("div", "tbl");
  const bar = el("div", "tbl-bar");
  const search = el("input", "ui-input tbl-search");
  search.type = "search";
  search.placeholder = `Search ${opts.name}`;
  search.setAttribute("aria-label", `Search ${opts.name}`);
  let cancel = () => {};
  search.addEventListener("input", () => {
    cancel();
    cancel = opts.later(() => update({ ...state, q: search.value }), 200);
  });
  // Phones: the filters fold behind one button so the sticky bar stays one line.
  const toggle = el("button", "ui-button ui-button--ghost ui-button--sm tbl-toggle", "Filters");
  toggle.type = "button";
  toggle.setAttribute("aria-expanded", "false");
  toggle.addEventListener("click", () => {
    const open = root.classList.toggle("tbl--open");
    toggle.setAttribute("aria-expanded", String(open));
  });
  bar.append(search, toggle);

  const inputs = new Map                                              ();
  for (const f of filters) {
    if (f.kind === "select") {
      const select = el("select", "ui-input tbl-filter");
      select.setAttribute("aria-label", f.label);
      select.append(el("option", undefined, `All ${f.label.toLowerCase()}`));
      (select.firstChild                     ).value = "";
      for (const [value, text] of f.options) {
        const option = el("option", undefined, text);
        option.value = value;
        select.append(option);
      }
      select.addEventListener("change", () => update({ ...state, f: { ...state.f, [f.key]: select.value } }));
      inputs.set(f.key, select);
      bar.append(select);
      continue;
    }
    if (f.kind === "text") {
      const input = el("input", "ui-input tbl-filter");
      input.type = "search";
      input.placeholder = f.label;
      input.setAttribute("aria-label", f.label);
      input.addEventListener("change", () =>
        update({ ...state, f: { ...state.f, [f.key]: input.value.trim() } }),
      );
      inputs.set(f.key, input);
      bar.append(input);
      continue;
    }
    if (f.kind === "check") {
      const box = el("label", "tbl-check");
      const input = el("input");
      input.type = "checkbox";
      input.addEventListener("change", () =>
        update({ ...state, f: { ...state.f, [f.key]: input.checked ? "1" : "" } }),
      );
      box.append(input, f.label);
      inputs.set(f.key, input);
      bar.append(box);
      continue;
    }
    const group = el("span", "tbl-range");
    group.setAttribute("role", "group");
    group.setAttribute("aria-label", f.label);
    group.append(el("span", "tbl-range__label", f.label));
    for (const end of ["min", "max"]         ) {
      const input = el("input", "ui-input");
      const key = `${f.key}_${end}`;
      if (f.unit === "date") input.type = "date";
      else {
        input.type = "number";
        input.min = "0";
        input.step = "0.01";
        input.inputMode = "decimal";
        input.placeholder = end === "min" ? "min $" : "max $";
      }
      input.setAttribute("aria-label", `${f.label} ${end === "min" ? "from" : "to"}`);
      input.addEventListener("change", () => update({ ...state, f: { ...state.f, [key]: input.value } }));
      inputs.set(key, input);
      group.append(input);
    }
    bar.append(group);
  }

  const count = el("span", "tbl-count");
  count.setAttribute("role", "status");
  const clear = el("button", "ui-button ui-button--ghost ui-button--sm tbl-clear", "Clear filters");
  clear.type = "button";
  clear.addEventListener("click", () => update({ q: "", sort: state.sort, f: {} }));
  bar.append(count, clear);

  const table = el("table", "tbl-table");
  const head = el("tr");
  const ths = columns.map((c) => {
    const th = el("th");
    th.scope = "col";
    if (c.num) th.className = "num";
    const button = el("button", "tbl-sort", c.label);
    button.type = "button";
    button.addEventListener("click", () => update({ ...state, sort: nextSort(state.sort, c) }));
    th.append(button);
    head.append(th);
    return th;
  });
  const thead = el("thead");
  thead.append(head);
  const tbody = el("tbody");
  table.append(thead, tbody);
  const empty = el("p", "tbl-empty muted");
  // The footer of a server-paged list: a sentinel that loads the next page, a button as fallback.
  const foot = el("div", "tbl-foot");
  const moreButton = el("button", "ui-button ui-button--ghost ui-button--sm", "Load more");
  moreButton.type = "button";
  const endText = el("span", "tbl-end muted");
  foot.append(moreButton, endText);
  let end                             = "end";
  const { remote } = opts;
  if (remote) {
    moreButton.addEventListener("click", () => end === "more" && remote.more());
    const View = doc.defaultView                                       ;
    if (View?.IntersectionObserver) {
      new View.IntersectionObserver((entries) => {
        if (entries.some((e) => e.isIntersecting) && end === "more") remote.more();
      }).observe(foot);
    }
    root.append(bar, table, empty, foot);
  } else root.append(bar, table, empty);

  const expanded = new Set        ();
  const keyOf = opts.key ?? ((row   ) => String(rows.indexOf(row)));

  function update(next            ) {
    state = next;
    opts.onChange(state);
    draw();
  }

  function draw() {
    if (doc.activeElement !== search) search.value = state.q;
    for (const [key, input] of inputs)
      if (input.type === "checkbox") (input                    ).checked = state.f[key] === "1";
      else input.value = state.f[key] ?? "";
    ths.forEach((th, i) => {
      const key = columns[i]?.key;
      th.setAttribute(
        "aria-sort",
        state.sort === key ? "ascending" : state.sort === `-${key}` ? "descending" : "none",
      );
    });
    const shown = remote
      ? applyTable(rows, columns, [], { ...state, q: "" })
      : applyTable(rows, columns, filters, state);
    const filtered = Boolean(state.q.trim() || Object.values(state.f).some(Boolean));
    const total = remote?.total?.();
    count.textContent = remote
      ? `${rows.length}${total == null ? "" : ` of ${total}`} ${remote.noun} loaded`
      : filtered
        ? `${shown.length} of ${rows.length}`
        : `${rows.length} shown`;
    const active = Object.values(state.f).filter(Boolean).length;
    toggle.textContent = active ? `Filters (${active})` : "Filters";
    clear.disabled = !filtered;
    // Every loaded row is drawn: a few hundred plain rows are cheap, and windowing them left gaps.
    tbody.replaceChildren(
      ...shown.flatMap((row) => {
        const tr = el("tr");
        for (const c of columns) {
          const td = el("td", c.num ? "num" : undefined);
          td.dataset.label = c.label;
          td.append(c.cell ? c.cell(row) : c.text(row));
          tr.append(td);
        }
        const { detail, label } = opts;
        const key = keyOf(row);
        tr.dataset.key = key;
        const isOpen = expanded.has(key);
        const open = detail
          ? () => {
              if (!expanded.delete(key)) expanded.add(key);
              draw();
            }
          : opts.open && (() => opts.open?.(row));
        if (open) {
          tr.className = "open";
          tr.tabIndex = 0;
          tr.setAttribute("role", "button");
          if (detail) tr.setAttribute("aria-expanded", String(isOpen));
          if (label) tr.setAttribute("aria-label", label(row));
          tr.addEventListener("click", open);
          tr.addEventListener("keydown", (e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              open();
            }
          });
        }
        if (!detail || !isOpen) return [tr];
        const more = el("tr", "tbl-detail");
        const td = el("td");
        td.colSpan = columns.length;
        td.append(detail(row));
        more.append(td);
        return [tr, more];
      }),
    );
    moreButton.hidden = end !== "more";
    endText.textContent =
      end === "loading" ? "Loading…" : end === "end" && rows.length ? `End of ${remote?.noun}` : "";
    table.hidden = shown.length === 0;
    empty.hidden = shown.length > 0;
    // A search that finds nothing says so in its own words, not with the empty-list text.
    empty.textContent = state.q.trim()
      ? `No rows match "${state.q.trim()}"`
      : rows.length
        ? "Nothing matches these filters."
        : opts.empty;
  }

  draw();
  return {
    el: root,
    setRows(next     ) {
      rows = next;
      draw();
    },
    setState(next            ) {
      state = next;
      draw();
    },
    setEnd(next                            ) {
      end = next;
      draw();
    },
    state: () => state,
    /** The rows the filters and search leave, in the current order. */
    visible: () => applyTable(rows, columns, filters, state),
  };
}

// The Overview tab: health in one line, the task funnel, money in/out/kept, and readable trend charts.
// server.ts inlines this file (types stripped) into ops.html.


                                            
                      
                   
                                    
             
                           
                     
                         
               
  

const SVG = "http://www.w3.org/2000/svg";

function node                                       (
  doc          ,
  tag   ,
  cls                ,
  ...kids       
) {
  const el = doc.createElement(tag);
  if (cls) el.className = cls;
  for (const kid of kids) if (kid != null) el.append(kid);
  return el;
}

/** An outline icon from the inlined sprite; with a label it is announced (and shown as a tooltip). */
function icon(doc          , id        , label         ) {
  const svg = doc.createElementNS(SVG, "svg");
  svg.setAttribute("class", "ui-icon");
  if (label) {
    svg.setAttribute("role", "img");
    svg.setAttribute("aria-label", label);
    const title = doc.createElementNS(SVG, "title");
    title.textContent = label;
    svg.append(title);
  } else svg.setAttribute("aria-hidden", "true");
  const use = doc.createElementNS(SVG, "use");
  use.setAttribute("href", `#${id}`);
  svg.append(use);
  return svg;
}

/** Plain names for the providers the server reports, as on /status. */
const SERVICES                                   = {
  messaging: ["Texting", "i-message"],
  email: ["Email", "i-mail"],
  payments: ["Payments", "i-cash"],
  storage: ["Photos", "i-camera"],
  vision: ["Safety check", "i-shield"],
  geo: ["Place lookup", "i-pin"],
};
const service = (name        ) => SERVICES[name] ?? [name, "i-info"];
/** Who does the work when a service is live (main.ts); the photo check is clef when configured. */
const providerOf = (name        , hl        ) =>
  name === "vision"
    ? hl.classifier.startsWith("clef")
      ? "clef"
      : "Claude"
    : ((
        {
          messaging: "Inkbox",
          email: "Primitive",
          payments: "Stripe",
          storage: "InsForge",
          geo: "Nominatim",
        }                          
      )[name] ?? name);

function renderHealth(doc          , root             , hl        ) {
  const all = Object.entries(hl.providers);
  const off = all.filter(([, mode]) => mode !== "live");
  // Icon and name for each service; hover or focus tells the provider and state.
  const items = all.map(([name, mode]) => {
    const [label, id] = service(name);
    const live = mode === "live";
    const tip = `${label}: ${live ? `${providerOf(name, hl)}, live` : "simulated"}`;
    const li = node(doc, "li", `svc__item ${live ? "is-live" : "is-off"}`, icon(doc, id), label);
    if (!live) li.append(node(doc, "span", "svc__state", " · off"));
    li.tabIndex = 0;
    li.setAttribute("aria-label", tip);
    li.dataset.tip = tip;
    return li;
  });
  const grid = all.length ? node(doc, "ul", "svc__grid", ...items) : null;
  const summary = node(
    doc,
    "p",
    `svc${off.length ? " svc--off" : ""}`,
    !all.length
      ? "No services reported"
      : off.length
        ? `${all.length - off.length} of ${all.length} services live`
        : `All ${all.length} services live`,
  );
  // Only what is not live gets a line of its own.
  const problems = off.length
    ? node(
        doc,
        "ul",
        "svc-off",
        ...off.map(([name]) => {
          const [label, id] = service(name);
          return node(
            doc,
            "li",
            null,
            icon(doc, id),
            `${label} is simulated: nothing real is sent or charged.`,
          );
        }),
      )
    : null;
  const meta                  = [
    [
      "Database",
      hl.db_error
        ? node(doc, "span", "ui-badge ui-badge--danger", "failing")
        : hl.db === "insforge"
          ? "Hosted Postgres"
          : "Local Postgres",
    ],
    ["Safety check", hl.classifier],
    ["Node", hl.node],
  ];
  if (hl.commit) meta.push(["Commit", node(doc, "code", null, hl.commit.slice(0, 10))]);
  const dl = node(
    doc,
    "dl",
    "meta",
    ...meta.flatMap(([k, v]) => [node(doc, "dt", null, k), node(doc, "dd", null, v)]),
  );
  root.replaceChildren(...[summary, grid, problems, dl].filter((x) => x != null));
}

/** "needs_review" → "Needs review". */
const statusLabel = (status        ) => {
  const words = status.replace(/_/g, " ");
  return words.charAt(0).toUpperCase() + words.slice(1);
};
const FUNNEL = ["dispatched", "claimed", "submitted", "verified", "paid"];
/** After the funnel: the states that need a decision, then how the rest ended. */
const AFTER = ["needs_review", "disputed", "expired", "refunded"];
const TINT                         = { needs_review: " is-danger", disputed: " is-warn" };

/** One column per task state; each opens the Tasks tab filtered to it. Attention columns tint when > 0. */
function renderFunnel(doc          , root             , statuses                        ) {
  // Bars scaled to the busiest state: where tasks are piling up shows at a glance.
  const all = [...FUNNEL, ...AFTER];
  const top = Math.max(1, ...all.map((s) => statuses[s] ?? 0));
  const steps = node(
    doc,
    "ol",
    "funnel",
    ...all.map((s) => {
      const n = statuses[s] ?? 0;
      const bar = node(doc, "span", "funnel__bar");
      bar.style.height = `${(n / top) * 100}%`;
      const link = node(
        doc,
        "a",
        `funnel__step${n ? "" : " is-zero"}${LIVE.includes(s) && n ? " is-live" : ""}${n ? (TINT[s] ?? "") : ""}${s === AFTER[0] ? " is-first-after" : ""}`,
        node(doc, "span", "funnel__track", bar),
        node(doc, "b", null, String(n)),
        node(doc, "span", "funnel__label", statusLabel(s)),
      );
      link.href = `#tasks?status=${s}`;
      link.setAttribute("aria-label", `${statusLabel(s)}: ${n}. Show in Tasks`);
      return node(doc, "li", null, link);
    }),
  );
  root.replaceChildren(steps);
}

const MONEY                                 = [
  [
    "In",
    [
      ["topup", "Top-ups"],
      ["escrow", "Escrowed"],
    ],
  ],
  [
    "Out",
    [
      ["release", "Released to workers"],
      ["refund", "Refunded to agents"],
      ["payout", "Paid out (Stripe)"],
    ],
  ],
  ["Kept", [["fee", "Fees"]]],
];

/** Money in, out and kept over 24 h, one row group each, amounts aligned. */
function renderMoney(doc          , root             , m                        ) {
  root.replaceChildren(
    ...MONEY.map(([group, rows]) => {
      const body = node(doc, "tbody");
      rows.forEach(([key, label], i) => {
        const tr = node(doc, "tr");
        if (i === 0) {
          const th = node(doc, "th", null, group);
          th.scope = "rowgroup";
          th.rowSpan = rows.length;
          tr.append(th);
        }
        tr.append(node(doc, "td", null, label), node(doc, "td", "num", usd(m[key])));
        body.append(tr);
      });
      return body;
    }),
  );
}

                         
                
                   
                                                                                  
                  
               
                                 
                
  
const bucketTime = (key        ) => Date.parse(`${key.replace(" ", "T")}Z`);

/**
 * One trend card: the latest value large, the line scaled from 0 to its max (both labelled), a dot on the
 * latest point, and a tooltip with the bucket time and value under the pointer or the arrow keys.
 */
function chartCard(doc          , spec           , clock                        ) {
  const fmt = spec.format ?? String;
  const { values } = spec;
  const max = Math.max(0, ...values);
  const scale = max || 1;
  const n = Math.max(1, values.length - 1);
  const x = (i        ) => (i / n) * 100;
  const y = (v        ) => 40 - (v / scale) * 38;
  const pts = values.map((v, i) => `${x(i)},${y(v)}`).join(" ");
  const svg = doc.createElementNS(SVG, "svg");
  svg.setAttribute("viewBox", "0 0 100 40");
  svg.setAttribute("preserveAspectRatio", "none");
  svg.setAttribute("aria-hidden", "true");
  const shape = (tag        , cls        , points        ) => {
    const el = doc.createElementNS(SVG, tag);
    el.setAttribute("class", cls);
    el.setAttribute("points", points);
    return el;
  };
  svg.append(shape("polygon", "area", `0,40 ${pts} 100,40`), shape("polyline", "line", pts));

  const last = values.length - 1;
  const dot = node(doc, "span", "chart__dot");
  const cursor = node(doc, "span", "chart__cursor");
  const tip = node(doc, "span", "chart__tip");
  tip.setAttribute("role", "status");
  cursor.hidden = true;
  tip.hidden = true;
  const place = (el             , i        ) => {
    el.style.left = `${x(i)}%`;
    el.style.top = `${(y(values[i]          ) / 40) * 100}%`;
  };
  if (last >= 0) place(dot, last);
  else dot.hidden = true;
  let at = last;
  const show = (i        ) => {
    at = Math.min(last, Math.max(0, i));
    const time = spec.times[at];
    tip.textContent = `${time ? clock(bucketTime(time)) : ""} ${fmt(values[at]          )}`.trim();
    place(tip, at);
    place(cursor, at);
    tip.hidden = false;
    cursor.hidden = false;
  };
  const hide = () => {
    tip.hidden = true;
    cursor.hidden = true;
  };

  const plot = node(
    doc,
    "div",
    "chart__plot",
    svg,
    node(doc, "span", "chart__axis chart__axis--max", fmt(max)),
    node(doc, "span", "chart__axis chart__axis--min", fmt(0)),
    cursor,
    dot,
    tip,
  );
  plot.tabIndex = last >= 0 ? 0 : -1;
  plot.setAttribute(
    "aria-label",
    `${spec.label}: now ${fmt(values[last] ?? 0)}, max ${fmt(max)}. Arrow keys read each point.`,
  );
  plot.addEventListener("pointermove", (e) => {
    const box = plot.getBoundingClientRect();
    show(Math.round(((e.clientX - box.left) / (box.width || 1)) * n));
  });
  plot.addEventListener("pointerleave", hide);
  plot.addEventListener("blur", hide);
  plot.addEventListener("focus", () => show(at));
  plot.addEventListener("keydown", (e) => {
    const step = { ArrowLeft: -1, ArrowRight: 1, Home: -last, End: last }[e.key];
    if (step === undefined) return;
    e.preventDefault();
    show(at + step);
  });

  return node(
    doc,
    "div",
    `chart${spec.bad ? " bad" : ""}`,
    node(doc, "h3", null, spec.label),
    node(doc, "p", "chart__now", fmt(values[last] ?? 0)),
    node(doc, "p", "chart__note", spec.note),
    plot,
  );
}

                          
                     
                     
                   
                   
                  
                                  
                                              
  

/** The chart specs for a series payload, in reading order. */
function seriesCharts(s            )              {
  const minutes = s.minutes ?? [];
  const reqs = sum(s.requests);
  const errs = sum(s.errors);
  const rate = s.requests.map((r, i) => (r ? ((s.errors[i]          ) / r) * 100 : 0));
  const statuses = Object.keys(s.tasks);
  const tasks              = statuses.length
    ? statuses.map((st) => {
        const counts = s.tasks[st]            ;
        return {
          label: `${statusLabel(st)} per hour`,
          values: counts,
          times: s.hours,
          note: `${sum(counts)} in 24 h`,
          bad: st in TINT && sum(counts) > 0,
        };
      })
    : [{ label: "Tasks per hour", values: s.hours.map(() => 0), times: s.hours, note: "None in 24 h" }];
  return [
    { label: "Requests per minute", values: s.requests, times: minutes, note: `${reqs} in 2 h` },
    {
      label: "Server errors",
      values: rate,
      times: minutes,
      note: `${errs} of ${reqs} requests failed in 2 h`,
      format: (v) => `${v.toFixed(1)}%`,
      bad: errs > 0,
    },
    {
      label: "Response time, slowest 5%",
      values: s.p95_ms,
      times: minutes,
      note: "p95 per minute over 2 h",
      format: (v) => `${Math.round(v)} ms`,
    },
    ...tasks,
    {
      label: "Payouts per hour",
      values: s.payouts.ok,
      times: s.hours,
      note: `${sum(s.payouts.ok)} paid, ${sum(s.payouts.failed)} failed in 24 h`,
      bad: sum(s.payouts.failed) > 0,
    },
  ];
}

// The Logs tab: icons for level and source, compact rows with details, and merging pages and live
// events without duplicates. server.ts inlines this file (types stripped) into ops.html.


                        
              
             
               
                
                  
                          
                                 
  

/** Event kinds as people say them, with their outline icon. */
const SOURCES                                   = {
  http: ["Web request", "i-globe"],
  mcp: ["MCP", "i-plug"],
  call: ["Agent call", "i-plug"],
  task: ["Task", "i-pin"],
  ledger: ["Money", "i-cash"],
  payout: ["Payout", "i-cash"],
  text: ["Texting", "i-message"],
  reply: ["Text reply", "i-message"],
  email: ["Email", "i-mail"],
  webhook: ["Webhook", "i-plug"],
  safety: ["Safety check", "i-shield"],
  vision: ["Photo check", "i-camera"],
  ticket: ["Support", "i-message"],
  ops: ["Operator", "i-eye"],
  auth: ["Sign-in", "i-shield"],
  log: ["Server log", "i-info"],
};
const LEVELS                                   = {
  info: ["Info", "i-info"],
  warn: ["Warning", "i-alert"],
  error: ["Error", "i-error"],
};
const sourceOf = (kind        )                   => SOURCES[kind] ?? [kind, "i-info"];
const levelOf = (level        )                   => LEVELS[level] ?? [level, "i-info"];

/** Labelled icon in a span that carries the tone. */
function badgeIcon(doc          , [label, id]                  , cls        ) {
  const span = doc.createElement("span");
  span.className = cls;
  span.append(icon(doc, id, label));
  return span;
}

const eventKey = (e          ) => (e.id == null ? `${e.at} ${e.kind} ${e.summary}` : String(e.id));

/** `head` then `tail`, newest first, each event once (by id). */
function mergeEvents(head            , tail            ) {
  const seen = new Set        ();
  return [...head, ...tail].filter((e) => {
    const key = eventKey(e);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

/** The expanded part of a row: full summary, the task to filter by, and the redacted data. */
function eventDetail(doc          , e          , filterTask                      ) {
  const box = doc.createElement("div");
  box.className = "ev-detail";
  const summary = doc.createElement("p");
  summary.className = "ev-detail__summary";
  summary.textContent = e.summary;
  box.append(summary);
  if (e.task_id) {
    const task = e.task_id;
    const button = doc.createElement("button");
    button.type = "button";
    button.className = "ui-button ui-button--ghost ui-button--sm";
    button.textContent = `Only task ${task.slice(0, 8)}`;
    button.addEventListener("click", (ev) => {
      ev.stopPropagation();
      filterTask(task);
    });
    box.append(button);
  }
  if (e.data && Object.keys(e.data).length) {
    const pre = doc.createElement("pre");
    pre.className = "ev-detail__data";
    pre.textContent = JSON.stringify(e.data, null, 2);
    box.append(pre);
  }
  return box;
}

// Decision controls for the review and ticket panels: one primary action, the rest in a menu, a
// labelled note that grows, an inline confirm step, and a clear result. Plus toasts. server.ts inlines
// this file (types stripped) into ops.html.


                                                       
                      
                
                                                                         
                  
                                                                          
               
                                       
                                          
  
                                 
                  
                 
                                                           
                                                        
                                   
             
  

const el =                                        (doc          , tag   , cls         , text         ) => {
  const node = doc.createElement(tag);
  if (cls) node.className = cls;
  if (text != null) node.textContent = text;
  return node;
};
const button = (doc          , text        , cls        ) => {
  const b = el(doc, "button", `ui-button ui-button--sm ${cls}`, text);
  b.type = "button";
  return b;
};

function actionArea(doc          , opts                   ) {
  const root = el(doc, "div", "decide");
  const field = el(doc, "div", "decide__field");
  const noteId = `${opts.id}-note`;
  const label = el(doc, "label", "decide__label", opts.note.label);
  label.htmlFor = noteId;
  const note = el(doc, "textarea", "ui-input decide__note");
  note.id = noteId;
  note.rows = 2;
  note.maxLength = 500;
  const hint = el(doc, "p", "decide__hint", opts.note.hint);
  hint.id = `${noteId}-hint`;
  note.setAttribute("aria-describedby", hint.id);
  // Grows with what is typed (field-sizing does this in CSS where supported; this covers the rest).
  note.addEventListener("input", () => {
    note.style.height = "auto";
    note.style.height = `${note.scrollHeight}px`;
    note.removeAttribute("aria-invalid");
  });
  field.append(label, note, hint);

  const status = el(doc, "p", "decide__status");
  status.setAttribute("role", "status");
  const row = el(doc, "div", "decide__row");
  root.append(field, row, status);

  let menuOpen = false;
  const say = (tone                     , text        ) => {
    status.className = `decide__status${tone ? ` is-${tone}` : ""}`;
    status.replaceChildren(...(tone ? [icon(doc, tone === "ok" ? "i-check" : "i-error")] : []), text);
  };

  function idle(focus              ) {
    menuOpen = false;
    const primary = button(doc, opts.primary.label, `ui-button--${opts.primary.tone}`);
    primary.addEventListener("click", () => confirming(opts.primary));
    const items         = [primary];
    if (opts.more.length) {
      const toggle = button(doc, "More actions", "ui-button--ghost decide__more");
      toggle.setAttribute("aria-haspopup", "menu");
      toggle.setAttribute("aria-expanded", "false");
      const menu = el(doc, "div", "decide__menu");
      menu.setAttribute("role", "menu");
      menu.hidden = true;
      const entries = opts.more.map((action) => {
        const item = el(doc, "button", `decide__item is-${action.tone}`, action.label);
        item.type = "button";
        item.setAttribute("role", "menuitem");
        item.tabIndex = -1;
        item.addEventListener("click", () => confirming(action));
        return item;
      });
      const show = (open         ) => {
        menuOpen = open;
        menu.hidden = !open;
        toggle.setAttribute("aria-expanded", String(open));
        if (open) entries[0]?.focus();
      };
      toggle.addEventListener("click", () => show(!menuOpen));
      menu.addEventListener("keydown", (e) => {
        const at = entries.indexOf(doc.activeElement                     );
        const next = { ArrowDown: at + 1, ArrowUp: at - 1, Home: 0, End: entries.length - 1 }[e.key];
        if (e.key === "Escape") {
          e.preventDefault();
          show(false);
          toggle.focus();
        } else if (next !== undefined) {
          e.preventDefault();
          entries[(next + entries.length) % entries.length]?.focus();
        }
      });
      menu.append(...entries);
      const wrap = el(doc, "div", "decide__menuwrap");
      wrap.append(toggle, menu);
      items.push(wrap);
    }
    row.replaceChildren(...items);
    (focus ?? null)?.focus();
  }

  // The confirm step replaces the buttons in place: it says what will happen, the confirm button repeats the verb.
  function confirming(action        ) {
    if (opts.note.required && !note.value.trim()) {
      note.setAttribute("aria-invalid", "true");
      say("error", `Write a note first. ${opts.note.hint}`);
      note.focus();
      idle();
      return;
    }
    say("", "");
    const question = el(doc, "span", "decide__question", action.confirm);
    const yes = button(doc, action.verb, `ui-button--${action.tone === "ghost" ? "primary" : action.tone}`);
    const no = button(doc, "Cancel", "ui-button--ghost");
    yes.addEventListener("click", () => run(action, yes, no));
    no.addEventListener("click", () => idle());
    row.replaceChildren(question, yes, no);
    row.classList.add("is-confirming");
    row.onkeydown = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        row.classList.remove("is-confirming");
        idle();
      }
    };
    yes.focus();
  }

  async function run(action        , yes                   , no                   ) {
    yes.disabled = true;
    no.disabled = true;
    yes.textContent = `${action.verb}…`;
    const outcome = await action.run(note.value.trim()).catch(
      (err         )          => ({
        ok: false,
        message: `Failed: ${err instanceof Error ? err.message : err}`,
      }),
    );
    row.classList.remove("is-confirming");
    row.onkeydown = null;
    if (!outcome.ok) {
      say("error", outcome.message);
      idle();
      return;
    }
    // Decided: the area locks; the list behind refreshes on its own.
    say("ok", outcome.message);
    note.disabled = true;
    row.replaceChildren();
    opts.toast(outcome.message);
  }

  idle();
  return root;
}

/** Bottom-of-screen toasts: polite, one at a time, 4 s each, paused while the tab is hidden. */
function createToaster(doc          , later                                            ) {
  const region = el(doc, "div", "toasts");
  region.setAttribute("role", "status");
  region.setAttribute("aria-live", "polite");
  doc.body.append(region);
  let cancel = () => {};
  let left = 0;
  let started = 0;
  const now = () => doc.defaultView?.performance.now() ?? 0;
  const close = () => {
    cancel();
    region.firstElementChild?.classList.add("is-leaving");
    cancel = later(() => region.replaceChildren(), 200);
  };
  const arm = () => {
    started = now();
    cancel = later(close, left);
  };
  doc.addEventListener("visibilitychange", () => {
    if (!region.firstElementChild || region.firstElementChild.classList.contains("is-leaving")) return;
    if (doc.visibilityState === "hidden") {
      cancel();
      left = Math.max(0, left - (now() - started));
    } else arm();
  });
  return (message        ) => {
    cancel();
    const toast = el(doc, "div", "toast");
    toast.append(icon(doc, "i-check"), message);
    region.replaceChildren(toast);
    left = 4000;
    arm();
  };
}

